namespace BioChain.AnalysisFramework.BigFive;

// Big Five (OCEAN) prototype descriptions per chemical.
// Each pole emphasizes DIFFERENT chemicals with genuinely distinct vocabulary,
// so embedding vectors are naturally far apart in semantic space.
// HIGH poles describe chemicals that drive that trait direction;
// LOW poles describe different chemicals that drive the opposite direction.
// This avoids the pitfall of "dopamine elevated" vs "dopamine low" sharing
// 80% vocabulary and producing near-identical embeddings.
//
// PrototypeVersion must be bumped whenever descriptions change to force re-embedding.
public static class BigFivePrototypes
{
    public const int PrototypeVersion = 3;

    public static readonly Dictionary<(string Pole, string Chemical), string> ChemicalDescriptions = new()
    {
        // ══════════════════════════════════════════════════════════════
        // OPENNESS HIGH — curious, creative, abstract, novelty-seeking
        // Lead chemicals: dopamine, glutamate, bdnf, endocannabinoid, norepinephrine, acetylcholine, orexin, dhea, thyroid
        // ══════════════════════════════════════════════════════════════
        [("openness_high", "dopamine")] = "Novelty-driven exploration fueled by D4 receptor polymorphism in prefrontal cortex. VTA phasic bursting generates anticipatory excitement for unfamiliar stimuli. Divergent thinking emerges from mesolimbic reward for discovering unexpected patterns. Creative association and intellectual risk-taking rewarded through ventral striatal activation.",
        [("openness_high", "glutamate")] = "NMDA receptor NR2B subunits in hippocampus enable extended coincidence detection for remote conceptual associations. Synaptic plasticity supports rapid formation of novel cross-domain connections. Metabotropic mGluR5 activation in prefrontal cortex drives creative insight and abstract reasoning. Mental frameworks assembled through excitatory cascade.",
        [("openness_high", "bdnf")] = "Rapid neuroplasticity through TrkB signaling in hippocampus and cortex. Val66Val polymorphism with high activity-dependent secretion enables fast encoding of novel frameworks. BDNF-CREB cascade supports learning new paradigms and abstract conceptual models. Neural growth factor for intellectual expansion.",
        [("openness_high", "endocannabinoid")] = "CB1 retrograde signaling loosens rigid top-down perceptual constraints. Anandamide tone in prefrontal cortex supports cognitive flexibility and openness to alternative perspectives. 2-AG modulation enhances divergent processing and free-associative thought. Inner perceptual boundaries become fluid and permeable.",
        [("openness_high", "norepinephrine")] = "Locus coeruleus tonic mode enables broad attentional scanning across conceptual domains. Moderate arousal optimized for detecting unexpected connections between disparate ideas. Cognitive flexibility sustained through alpha-2A receptor engagement without tunnel vision. Wide-lens awareness scanning for novelty.",
        [("openness_high", "acetylcholine")] = "Muscarinic M1 receptor activation in entorhinal cortex supports associative memory linking across domains. Nucleus basalis projections enhance cross-domain pattern recognition and intellectual curiosity. Deep encoding of novel concepts through cholinergic attentional engagement. Knowledge integration across disciplines.",
        [("openness_high", "orexin")] = "OX1R/OX2R activation drives sustained wakefulness and motivational arousal for exploration. Lateral hypothalamic neurons fuel curiosity-driven energy for late-night ideation and discovery. Arousal system calibrated for adventure and intellectual pursuit rather than routine maintenance.",
        [("openness_high", "dhea")] = "High DHEA:cortisol ratio supports resilient exploration under uncertainty. Neurosteroid modulation preserves cognitive flexibility when navigating unfamiliar territory. Anti-stress buffering enables sustained creative engagement without defensive withdrawal.",
        [("openness_high", "thyroid")] = "TRα/TRβ receptor activation supports fast cognitive processing speed for rapid association formation. Mitochondrial energy in cortical neurons fuels extended creative cognition and abstract model-building.",

        // ══════════════════════════════════════════════════════════════
        // OPENNESS LOW — conventional, concrete, practical, routine-preferring
        // Lead chemicals: serotonin, gaba, vasopressin, cortisol, melatonin, progesterone, prolactin, dynorphin, crh
        // ══════════════════════════════════════════════════════════════
        [("openness_low", "serotonin")] = "Elevated 5-HT2A receptor density in sensory cortex anchors attention to concrete present-moment perception. Tryptophan hydroxylase-2 activity pattern favoring sensory precision over imagination. Stable dorsal raphe output calms the mind into practical clarity. Grounded awareness of tangible reality.",
        [("openness_low", "gaba")] = "Strong GABAergic inhibition in default mode network suppresses unstructured ideation and fantasy. PV+ interneuron tonic inhibition constrains associations to conventional semantic categories. Structured thought architecture preferred over free-association. Mental discipline through inhibitory braking.",
        [("openness_low", "vasopressin")] = "V1a receptor activation supports loyalty to established traditions and proven methods. Territorial maintenance of conventional worldview and familiar practices. Protective instinct toward tested approaches and institutional knowledge. Stability through precedent.",
        [("openness_low", "cortisol")] = "GR activation in amygdala creates mild aversion to ambiguous or unstructured situations. HPA axis reactivity treats novelty as potential threat requiring caution. Anticipatory stress response channels energy toward proven solutions. Safety in the known and tested.",
        [("openness_low", "melatonin")] = "MT1/MT2 receptor sensitivity precisely calibrated for consistent circadian rhythm. Pineal gland secretion supporting disciplined sleep-wake cycles and regular daily structure. Biological clock aligned with conventional scheduling and routine maintenance.",
        [("openness_low", "progesterone")] = "Allopregnanolone GABA-A positive modulation supports calm routine adherence and preference for predictable schedules. Sedating neurosteroid effect compatible with settled, structured lifestyle. Contentment within established frameworks.",
        [("openness_low", "prolactin")] = "Dopamine-prolactin balance shifted toward contentment with established knowledge. Satiation signal reduces drive to seek novel intellectual stimulation. Comfortable mastery of known domains preferred over restless exploration.",
        [("openness_low", "dynorphin")] = "Kappa-opioid receptor activation when forced out of comfort zone signals return to established patterns. KOR-mediated aversion creates discomfort with unfamiliar abstract concepts. Neurochemical preference for the concrete and proven.",
        [("openness_low", "crh")] = "CRHR1 activation triggered by open-ended ambiguity drives closure-seeking behavior. Structured resolution preferred over extended exploration. Anxiety from unanswered questions channels into practical problem-solving.",

        // ══════════════════════════════════════════════════════════════
