        // ══════════════════════════════════════════════════════════════
        [("conscientiousness_high", "serotonin")] = "5-HT2C receptor activation in ventral striatum inhibits impulsive action. High serotonergic tone in orbitofrontal cortex supports delay of gratification and systematic long-term planning. 5-HT1A autoreceptor desensitization maintains sustained behavioral control and patience.",
        [("conscientiousness_high", "gaba")] = "Strong GABAergic inhibition in ventral striatum suppresses impulsive responses. GABA-A fast inhibition via PV+ interneurons enables precise response selection. Self-discipline built on robust inhibitory control architecture. Behavioral braking system finely calibrated.",
        [("conscientiousness_high", "cortisol")] = "Optimal GR activation in prefrontal cortex drives anticipatory planning and deadline awareness. Moderate CRH-cortisol cascade channels productive urgency into structured preparation. Acute cortisol sharpens executive attention for methodical task completion.",
        [("conscientiousness_high", "vasopressin")] = "V1a receptor activation in lateral septum supports duty, loyalty, and protective behavior toward commitments. Territorial maintenance of structured environments and schedules. Deep sense of obligation and responsibility.",
        [("conscientiousness_high", "acetylcholine")] = "Muscarinic M1 receptor activation in prefrontal cortex and hippocampus sustains attention to detail. Cholinergic projections drive procedural memory consolidation for skill mastery. Attentional precision for quality control and error detection.",
        [("conscientiousness_high", "norepinephrine")] = "Alpha-2A receptor prefrontal enhancement at inverted-U optimum supports sustained selective attention. Locus coeruleus phasic mode for task-relevant stimuli filters distractions. Controlled arousal for methodical, step-by-step execution.",
        [("conscientiousness_high", "crh")] = "CRHR1 activation provides productive anticipatory concern about unfinished tasks and approaching deadlines. Stress channeled into preparation rather than avoidance. Task-completion urgency as motivational engine.",
        [("conscientiousness_high", "npy")] = "Y1 receptor anxiolytic effects support calm methodical execution even under pressure. NPY buffers performance anxiety enabling steady work output. Stress resilience through competence and preparation.",
        [("conscientiousness_high", "melatonin")] = "MT1/MT2 receptor sensitivity precisely calibrated for disciplined circadian rhythm. Consistent sleep-wake schedule supports reliable daily performance. Early bedtime, early rising, structured biological clock.",

        // ══════════════════════════════════════════════════════════════
        // CONSCIENTIOUSNESS LOW — spontaneous, flexible, casual
