        // ══════════════════════════════════════════════════════════════
        [("conscientiousness_low", "dopamine")] = "Phasic dopamine bursting in mesolimbic pathway chases immediate reward over delayed goals. D1 receptor maintenance of goal representations in prefrontal cortex inconsistent. Reward discounting steep — present pleasure valued far more than future payoff. Spontaneous pursuit of whatever feels exciting now.",
        [("conscientiousness_low", "endocannabinoid")] = "CB1 retrograde signaling loosens behavioral constraints and top-down control. High anandamide tone increases spontaneity and moment-to-moment adaptability. Flexibility over structure, flow over planning. Inner rigidity dissolved by cannabinoid modulation.",
        [("conscientiousness_low", "endorphins")] = "Mu-opioid receptor activation from spontaneous pleasures and immediate gratification. Beta-endorphin release rewards in-the-moment experiences and joyful improvisation. Hedonic present-focus rather than delayed achievement satisfaction.",
        [("conscientiousness_low", "orexin")] = "OX1R/OX2R activation inconsistent — arousal and motivational energy fluctuate with interest rather than schedule. Lateral hypothalamic drive responsive to mood and novelty rather than maintaining steady productive output.",
        [("conscientiousness_low", "enkephalins")] = "Delta-opioid receptor tone from present-moment enjoyment and sensory pleasure. Contentment from current experience without needing completed checklists. Baseline satisfaction independent of task completion.",
        [("conscientiousness_low", "progesterone")] = "Allopregnanolone modulation supports easy-going calm without disciplined structure. Sleep schedule follows energy and mood rather than clock. Relaxed disposition resistant to externally imposed schedules.",
        [("conscientiousness_low", "prolactin")] = "Dopamine-prolactin balance allows easy satisfaction and relaxation before tasks are fully complete. Content to pause, enjoy, and resume later. No urgency-driven compulsion to finish.",
        [("conscientiousness_low", "thyroid")] = "TRα/TRβ receptor activation supports cognitive function but energy output variable. Metabolic drive allocated responsively to interest rather than systematically to productive work.",
